package net.minecraft.world.entity.item;import net.minecraft.world.item.ItemStack;import net.minecraft.world.phys.Vec3;public class ItemEntity{public int tickCount=100;public boolean discarded;public ItemStack stack;public double x=.7,y=.2,z=.7;public ItemEntity(ItemStack stack){this.stack=stack;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public Vec3 position(){return new Vec3(x,y,z);}public boolean isRemoved(){return discarded;}public ItemStack getItem(){return stack;}public void setItem(Object stack){this.stack=(ItemStack)stack;}public void discard(){discarded=true;}}
